let pa, minwh, w_h, h_h; // width / height half
let clrHue = 42; // 35; // green hue
let clrGreen; // p5js color
let objs;

function setup() {
	const wantedAR = 4 / 3;
	let ar = windowWidth / windowHeight;
	let w = windowWidth,
		h = windowWidth / wantedAR;
	if (h > windowHeight) {
		h = windowHeight
		w = windowHeight * wantedAR;
	}
	minwh = min(w, h);
	createCanvas(w, h); // createCanvas(minwh, minwh);
	pixelDensity(1);
	pa = minwh * 0.05; // padding
	frameRate(30);
	w_h = width * 0.5;
	h_h = height * 0.5;
	colorMode(HSB, 100);

	// define objs
	clrGreen = color(clrHue, 100, 100)
	objs = [];
	objs.push(new ObjCircle(w_h - 10, h_h, 0, minwh * 0.3, clrGreen, false));
	objs.push(new ObjCircle(w_h + 10, h_h, PI, minwh * 0.3, color(0), true));
	objs.push(new ObjRect(w_h, h_h, PI, minwh * 0.3, clrGreen));
}

function windowResized() {
	setup();
	loop();
}

function draw() {
	background(0);
	noFill();

	// moving lines
	push();
	stroke(clrHue + 5, 75, 25); // stroke(clr, 75, 15);
	strokeWeight(2)
	const raster = 12;
	for (let y = -height, i = 0; y < height - pa; y += raster, i++) {
		// for (let y = pa, i = 0; y < height - pa; y += raster, i++) {
		let res1 = 0.1,
			res2 = 0.12;
		let val1 = map(y, -height, height, minwh * 0.05, minwh * 0.2);
		let val2 = map(y, -height, height, minwh * 0.2, minwh * 0.06);
		drawingContext.setLineDash([sin((i + frameCount) * res1) * val1, cos((i + frameCount) * res2) * val2]);
		let dy = frameCount % raster
		line(pa, y - dy, width - pa, y - dy);
	}
	pop();

	// objects
	objs = [...objs].sort((a, b) => a.z - b.z);
	for (let o of objs) {
		o.update();
		o.show();
	}

	// frame
	stroke(0); // stroke(clr, 75, 15);
	strokeWeight(pa)
	rect(pa * 0.5, pa * 0.5, width - 1 - pa, height - 1 - pa);
	stroke(clrHue, 75, 35); // stroke(clr, 75, 15);
	strokeWeight(6)
	rect(pa, pa, width - 1 - 2 * pa, height - 1 - 2 * pa);

	// // noLoop() removed for animation
}

class ObjCircle {
	constructor(x, y, a, d, c, o = false) {
		this.x = x;
		this.y = y;
		this.z = a;
		this.a = a;
		this.d = d;
		this.c = c;
		this.o = o; // outline + dashed
	}
	update() {
		const r = w_h - pa - this.d * 0.5;
		this.x = cos(this.a) * r + w_h;
		this.a = (this.a + 0.1) % TWO_PI;
		this.z = this.a;
	}
	show() {
		push()
		strokeWeight(1);
		stroke(clrGreen);
		if (this.o) {
			drawingContext.setLineDash([2, 10]);
		}
		noStroke();
		fill(0); // fill(this.c);
		translate(this.x, this.y);
		circle(0, 0, this.d)
		// if (this.o) {
			stroke(clrGreen);
			var raster = this.o ? 10 : 3;
			const radius = this.d * 0.5;
			for (let y = -radius; y < radius; y += raster) {
				for (let x = -radius; x < radius; x += raster) {
					if (dist(x, y, 0, 0) < radius) point(floor(x), floor(y));
				}
			}
		// }
		pop();
	}
}

class ObjRect {
	constructor(x, y, a, d, c) {
		this.x = x;
		this.y = y;
		this.z = a;
		this.a = a;
		this.d = d;
		this.c = c;
	}
	update() {
		var r = h_h - pa - this.d * 0.5;
		this.y = sin(this.a) * r + h_h;
		this.a = (this.a + 0.05) % TWO_PI;
	}
	show() {
		push()
		strokeWeight(1);
		stroke(this.c);
		noStroke()
		fill(0);
		rectMode(CENTER)
		translate(this.x, this.y);
		rotate(this.a);
		// drawingContext.shadowColor = "green";
		// drawingContext.shadowBlur = 100;
		rect(0, 0, this.d, this.d)

		var raster = 4;
		strokeWeight(1);
		stroke(this.c);
		for (let y = -this.d * 0.5; y < this.d * 0.5; y += raster) {
			for (let x = -this.d * 0.5; x < this.d * 0.5; x += raster) {
				point(floor(x), floor(y));
			}
		}
		pop();
	}
}
